def build(prefix=''):
 t=(b/'START-HERE.html').read_text()
 # Read from the existing design, replacing its weaker compositions.
 t=t.replace('</style>',extra+'</style>')
 t=re.sub(r'<span class="edition">.*?</span><a class="head-link".*?</a>', '<nav class="header-nav" aria-label="Welcome navigation"><a href="#collection">Your collection</a><a href="Studio.html#settings">Backup & settings</a><a class="nav-open" href="Studio.html">Enter studio ↗</a></nav>',t)
 t=t.replace('WELCOME TO YOUR CREATIVE DESK ✦','YOUR CLIENT CONTENT WORKSPACE')
 t=t.replace('Your client work.<br><em>A little more<br>together.</em>','From first brief<br>to <em>final yes.</em>')
 t=t.replace('Plan the content. Keep the final yes. Give every client a clearer, calmer experience.','Your brief, content plan, approvals and reports.<br>One clear home for the work your clients count on.')
 t=t.replace('Open my studio <span>↗</span>','Open my studio '+icon('arrow'))
 t=t.replace('Take the guided route →','Read the quick-start guide →')
 t=t.replace('Start with the fictional demo. Your changes stay on this device.','Includes a complete practice client. No account required. Export backups to keep your work.')
 t=t.replace('<span aria-hidden="true">✍️</span>', '<span>'+icon('pen')+'</span>').replace('<span aria-hidden="true">✓</span>','<span>'+icon('check')+'</span>').replace('<span aria-hidden="true">🌿</span>','<span>'+icon('chart')+'</span>')
 t=t.replace('<div class="section-head">','<div class="section-head" id="collection">').replace('THE REST OF YOUR COLLECTION','BUILT TO WORK TOGETHER').replace('The useful little extras.','Your complete client toolkit.').replace('Everything has its place.','Open a resource and put it to work.')
 cards=[]
 for ico,title,desc,label,img,link,cta in [
 ('book','Visual field guide','See the full workflow through diagrams, examples and clear review checks.','14-PAGE PDF','guide-cover.png','Documents/Visual-Field-Guide.pdf','Read the field guide'),
 ('folder','Client document studio','Customize six coordinated client layouts, from welcome packet to monthly report.','6 EDITABLE LAYOUTS','client-welcome.png','Documents/Editable-Documents.html','Customize your documents'),
 ('grid','Spreadsheet workspace','Plan content, track version-specific approval and review post-level results.','5-TAB XLSX','workbook-preview.png','Documents/Spreadsheet-Companion.xlsx','Open the workbook')]:
  cards.append('<a class="resource" href="'+link+'"><span class="file-label">'+label+'</span><div class="resource-preview"><img src="assets/'+img+'" alt="Preview of the included '+title.lower()+'"></div><div class="resource-body"><div class="resource-top"><span class="icon">'+icon(ico)+'</span><h3>'+title+'</h3></div><p>'+desc+'</p><span class="link">'+cta+icon('arrow')+'</span></div></a>')
 t=re.sub(r'<section class="resources">.*?</section>','<section class="resources" aria-label="Included resources">'+''.join(cards)+'</section>',t)
 t=t.replace('<span aria-hidden="true">💡</span>','<span>'+icon('check')+'</span>').replace('First visit? Keep it small.','Your first step: try one content card.')
 if prefix:
  t=re.sub(r'(href|src)="(?!#|https?:)([^"]+)"',lambda m:m[1]+'="'+prefix+m[2]+'"',t)
 return t
